function applyClipPreviewTransform(el,c){if(!el||!c)return;const screenRatio=(els.screen.clientWidth&&els.screen.clientHeight)?els.screen.clientWidth/els.screen.clientHeight:state.width/state.height,srcW=c.width||el.videoWidth||el.naturalWidth||state.width,srcH=c.height||el.videoHeight||el.naturalHeight||state.height,srcRatio=srcW/srcH;el.style.position='absolute';el.style.left=`${c.x??50}%`;el.style.top=`${c.y??50}%`;if(state.mismatchMode==='stretch'){el.style.width='100%';el.style.height='100%';el.style.objectFit='fill'}else if(state.mismatchMode==='fill'){if(srcRatio>=screenRatio){el.style.width='auto';el.style.height='100%'}else{el.style.width='100%';el.style.height='auto'}el.style.objectFit='cover'}else{if(srcRatio>=screenRatio){el.style.width='100%';el.style.height='auto'}else{el.style.width='auto';el.style.height='100%'}el.style.objectFit='contain'}el.style.maxWidth='none';el.style.maxHeight='none';el.style.aspectRatio=`${srcW} / ${srcH}`;el.style.transform=`translate(-50%,-50%) rotate(${c.rotation??0}deg) scale(${c.scale??1})`;el.style.opacity=String(c.opacity??1);el.style.transformOrigin='50% 50%'}
