for(let i=0;i<visibleLayers.length;i++){const o=visibleLayers[i],inputIndex=args.filter(x=>x==='-i').length;if(o.type==='gif'){const name=`layer_${i}.gif`;await ff.writeFile(name,await fetchFile(o.file));temps.push(name);args.push('-stream_loop','-1','-i',name)}else{const name=`layer_${i}.png`;await ff.writeFile(name,await pngFor(o,w,h));temps.push(name);args.push('-loop','1','-i',name)}layerInputs.push({o,inputIndex,index:i})}
