function setAssetView(view){state.mediaView=view;els.mediaView.classList.toggle('hidden',view!=='media');els.shapeView.classList.toggle('hidden',view!=='shapes');els.transitionView.classList.toggle('hidden',view!=='transitions');els.giphyView.classList.toggle('hidden',view!=='giphy');document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));if(view==='media')$('#mediaTool').classList.add('active');if(view==='shapes')$('#shapeTool').classList.add('active');if(view==='transitions')$('#transitionTool').classList.add('active');if(view==='giphy')$('#giphyTool').classList.add('active')}
