function updateGiphyChrome(){const hasKey=!!giphyKey();$('#giphyKeySetup').classList.toggle('hidden',hasKey);$('#giphySearchRow').classList.toggle('hidden',state.giphyMode!=='search');$('#giphyTrendingTab').classList.toggle('active',state.giphyMode==='trending');$('#giphySearchTab').classList.toggle('active',state.giphyMode==='search');document.querySelectorAll('[data-giphy-type]').forEach(b=>b.classList.toggle('active',b.dataset.giphyType===state.giphyType));$('#giphySectionTitle').textContent=(state.giphyMode==='trending'?'Tendencias':'Resultados')+' · '+(state.giphyType==='stickers'?'Stickers':'GIFs')+(GIPHY_BUILTIN_KEY?' · Conectado':'')}
